import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1204, own='cte_127.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)
H("875.d.1.A",3,"A technician at a golf-course shop notices a recalled throttle part on a customer's mower and warns him before returning it. She is acting on:","her ethical and legal responsibilities to the customer and the public",["a way to save time","a shop shortcut","an optional courtesy"],"Safety recalls carry legal duties.")
H("875.d.1.A",4,"A shop copies a competitor's service manual without permission. This is a problem mainly because it:","violates copyright law and professional ethics",["saves the shop money legally","is encouraged by industry","has no consequences"],"Copying protected manuals is illegal.")
H("875.d.1.B",3,"During a busy Saturday rush, a technician thanks each waiting customer and keeps his bay orderly. He is showing:","proper etiquette and professional behavior",["poor manners","disinterest","careless habits"],"Courtesy under pressure.")
H("875.d.1.B",4,"A coworker keeps interrupting while a customer describes a noise. The best professional response is to:","politely ask him to wait so the customer can finish",["join the interruption","leave the customer","raise your voice"],"Respect the speaker.")
H("875.d.1.C",3,"A technician arrives with clean coveralls, closed-toe boots and tied-back hair. This reflects appropriate:","personal appearance and hygiene for the workplace",["careless dress","unsafe clothing","poor hygiene"],"Neat dress shows professionalism.")
H("875.d.1.C",4,"Why should a technician wear closed-toe, slip-resistant boots in the engine shop?","they protect feet from dropped parts and oily floors",["they look fashionable","they are required by customers","they reduce engine noise"],"Footwear is PPE.")
H("875.d.1.D",3,"A technician emails a vendor a clear parts request, then calls a customer to confirm pickup time. She is using:","written and oral communication skills with employability in mind",["no communication","only gestures","avoidance"],"Both channels matter.")
H("875.d.1.D",4,"Which email to a supplier is most effective?","one that lists the part number, quantity and needed date",["one that says 'send stuff'","one with no subject line","one that is all in capital letters"],"Be specific.")
H("875.d.1.E",3,"A student drafts a clear procedure for adjusting a carburetor, with torque values, tools and cautions in numbered steps. This is advanced:","technical writing and preparation",["story writing","poetry","note passing"],"Precise instructions.")
H("875.d.1.E",4,"Compared with casual writing, technical writing for a repair manual should be:","exact, concise and organized",["decorative and vague","emotional and long","random and unordered"],"Manuals need clarity.")
H("875.d.1.F",3,"A student explains a four-stroke cycle to visiting parents, first with notes and later answering questions on the spot. She is demonstrating:","prepared and extemporaneous speaking skills",["silence","reading only","mumbling"],"Both prepared and impromptu.")
H("875.d.1.F",4,"Which habit makes a technical presentation more effective?","facing the audience and using plain language",["reading from the slide","speaking too softly","using only jargon"],"Engage the audience.")
H("875.d.2.A",3,"A student helps organize a fundraiser and a leadership retreat for her student organization. She is participating in:","planning and developing leadership and skill development activities",["avoiding responsibility","skipping events","ignoring teammates"],"Leadership is built by doing.")
H("875.d.2.A",4,"A student chairing a committee practices leadership best by:","assigning tasks fairly and following up on results",["doing everything alone","blaming others","avoiding decisions"],"Leaders delegate.")
H("875.d.2.B",3,"A student uses a career and technical student organization's mentor list, conferences and competitive events to meet employers. She is:","using organizational resources to grow her career",["wasting time","avoiding contacts","hiding her skills"],"Use resources.")
H("875.d.2.B",4,"A student organization chapter's competitive events benefit a student mainly by:","testing technical skills against industry standards",["removing practice","avoiding feedback","reducing teamwork"],"Contests set standards.")
H("875.d.2.C",3,"A student keeps a portfolio of her certificates, competition scores and completed repair projects. She is:","recording individual progress to document achievements",["hiding results","discarding work","avoiding records"],"Portfolios show growth.")
H("875.d.2.C",4,"A portfolio helps a graduate most when she is:","applying for a job and needs to show proof of her skills",["skipping the interview","avoiding references","shopping for tools"],"Proof of skill.")
H("875.d.3.A",3,"A shop owner invests in fuel-injected, battery-electric and hybrid outdoor equipment training. This reflects:","the impact of emerging technologies on the small engine industry",["no change in the trade","a drop in demand","a fixed market"],"Tech changes demand.")
H("875.d.3.A",4,"How might robotic mowers change the work of a small-engine shop?","technicians may service batteries, sensors and software",["no repairs will be needed","only paint work remains","shops must close"],"New skills required.")
H("875.d.3.B",3,"A group compares the effects of tighter emission rules and a technician shortage on repair shops. They are:","comparing and contrasting issues affecting the industry",["ignoring problems","avoiding discussion","describing a hobby"],"Compare issues.")
H("875.d.3.B",4,"Which is a contrast between the emissions issue and the technician-shortage issue?","emissions affects equipment design; the shortage affects staffing",["both are about paint","neither affects the shop","both only affect tires"],"Different impacts.")
H("875.d.3.C",3,"A student researches how fuel prices and overseas parts supply affect repair costs. She is describing:","local and global market conditions that impact the industry",["unrelated topics","only weather","personal hobbies"],"Markets affect cost.")
H("875.d.3.C",4,"A global supply-chain delay for engine parts is likely to cause:","longer repair times and higher parts prices",["faster repairs","lower prices only","no effect"],"Scarcity raises price.")
H("875.d.4.A",3,"A shop writes a plan to inspect lifts monthly, calibrate gauges yearly and review results to improve the plan. This involves developing, evaluating and performing:","preventative maintenance plans and systems",["random chores","vacation plans","sales plans"],"Plan, evaluate, perform.")
H("875.d.4.A",4,"Evaluating a preventative maintenance plan means:","reviewing records to see whether it prevents breakdowns",["ignoring the data","skipping inspections","raising prices"],"Check the plan's results.")
H("875.d.4.B",3,"A technician fills in the repair order with the customer's complaint, the cause found and the correction made. This is:","completing repair orders and paperwork for small engine work",["avoiding forms","hiding steps","losing data"],"The three Cs of a repair order.")
H("875.d.4.B",4,"The 'cause' line on a repair order records:","what was found to have created the customer's complaint",["the customer's phone","the shop's address","the date only"],"Cause explains the problem.")
H("875.d.4.C",3,"A technician combines $38 for parts, $15 in shop supplies and 1.5 hours at $70 an hour for a quote. He is:","estimating parts and labor costs on a repair order",["guessing blindly","hiding fees","skipping the math"],"Parts plus labor plus supplies.")
H("875.d.4.C",4,"A job needs $52 in parts and 3 hours at $65 per hour. The total estimate is:","$247",["$117","$195","$320"],"52 + 195 = 247.")
H("875.d.4.D",3,"A shop owner tracks how many billable hours each technician completes compared with hours worked. This describes:","business management principles such as technician productivity",["personal hobbies","paint selection","tire storage"],"Productivity is measured.")
H("875.d.4.D",4,"If a technician works 40 hours and bills 30 hours, his efficiency is:","75 percent",["25 percent","133 percent","30 percent"],"30 ÷ 40 = 0.75.")
H("875.d.4.E",3,"A technician locates a carburetor's float-height specification in the manufacturer's service manual. She is:","locating, reading and interpreting service repair information",["guessing","ignoring data","skipping reference"],"Look it up.")
H("875.d.4.E",4,"A technician finding conflicting specifications between a parts catalog and the engine's service manual should:","use the manufacturer's service manual for the correct specification",["pick the lower value","use the catalog only","guess the average"],"Service manual governs.")
H("875.d.5.A",3,"A technician consults a service manual, a manufacturer hotline and an online forum before diagnosing a hard-starting engine. She is:","using a variety of resources to research, troubleshoot and diagnose problems",["relying on guesses","ignoring references","skipping diagnosis"],"Use many resources.")
H("875.d.5.A",4,"Which resource is the most reliable for a torque specification?","the manufacturer's published service manual",["an anonymous forum post","a neighbor's memory","a social-media video"],"Official data first.")
H("875.d.5.B",3,"A student suspects a dirty jet is causing surging, changes only that one factor and tests the result. She is applying:","the scientific method to small engine technology",["random swapping","guessing","luck"],"Test one variable.")
H("875.d.5.B",4,"In the scientific method, an engine technician's hypothesis should be:","a testable explanation, such as 'a clogged jet causes the lean condition'",["a final conclusion","a random guess","an unrelated fact"],"Hypotheses are testable.")
H("875.d.6.A",3,"A student writes a proposal to restore a vintage tiller for a county fair, listing materials and a budget. She is:","developing a project proposal",["avoiding planning","skipping steps","ignoring costs"],"Proposals set goals.")
H("875.d.6.A",4,"A project proposal usually includes a:","timeline, a parts list and an estimated budget",["menu","dance routine","playlist"],"Complete plan.")
H("875.d.6.B",3,"A student logs each compression test, part replaced and date for every engine she repairs. She is:","developing and maintaining records for small engine work",["avoiding documentation","losing data","skipping notes"],"Keep service records.")
H("875.d.6.B",4,"Maintenance records help a shop when a customer returns with a warranty question because they:","show what was done and when",["hide past work","slow the process","replace the warranty"],"Records support claims.")
H("875.d.6.C",3,"A class records the compression of ten engines and shows the readings in a bar chart. They are:","collecting and organizing data in graphs, tables and charts",["avoiding data","ignoring numbers","only drawing pictures"],"Organize data visually.")
H("875.d.6.C",4,"A table of engine hours and oil-change dates is most useful for:","spotting patterns in maintenance intervals",["choosing paint","setting pay","planning a party"],"Tables reveal patterns.")
H("875.d.6.D",3,"A technician studies a chart of compression readings and sees one cylinder far below the others. She is:","analyzing and interpreting data from graphs, tables and charts",["ignoring results","guessing","avoiding reading"],"Interpret the data.")
H("875.d.6.D",4,"If a line graph of engine temperature shows a steady rise over 10 minutes, the engine is most likely:","heating up under load",["cooling down","off","freezing"],"Rising line means rising temperature.")
H("875.d.6.E",3,"A student calculates the engine's compression ratio by dividing total cylinder volume by the combustion chamber volume. She is:","using a mathematical formula for engine calculations",["painting","guessing","bargaining"],"Compression ratio is a ratio.")
H("875.d.6.E",4,"If total cylinder volume is 90 cc and clearance volume is 10 cc, the compression ratio is:","9 to 1",["8 to 1","80 to 1","100 to 1"],"90 ÷ 10 = 9.")
H("875.d.6.F",3,"A student uses Power = Voltage × Current to find the watts consumed by a small starter circuit. She is:","using a mathematical formula for electrical calculations",["measuring fuel","measuring oil","painting a wire"],"Power formula.")
H("875.d.6.F",4,"A circuit has 12 volts and 5 amps. The power used is:","60 watts",["17 watts","2.4 watts","7 watts"],"12 × 5 = 60.")
H("875.d.6.G",3,"A technician uses a digital multimeter to measure 6 ohms across a coil and 12 volts applied. She applies Ohm's law to predict:","the current flowing in the circuit",["the oil level","the tire pressure","the fuel octane"],"I = V ÷ R.")
H("875.d.6.G",4,"At 12 volts across 6 ohms, the current is:","2 amps",["72 amps","0.5 amps","18 amps"],"12 ÷ 6 = 2.")
H("875.d.6.H",3,"A technician finds no continuity through a charging coil and replaces it. She is applying:","electrical principles to diagnose and repair small engine components",["guesswork","paint","random swaps"],"Test, then repair.")
H("875.d.6.H",4,"An open circuit in the ignition kill-switch wire would cause:","no spark, because current cannot flow",["extra spark","stronger spark","a cooler engine"],"Open means no path.")
H("875.d.7.A",3,"A technician emails a quote and searches a supplier's website for a discontinued gasket. She is using:","personal management software such as email and Internet applications",["only paper","hand tools only","no software"],"Email and web aid work.")
H("875.d.7.A",4,"A shop's calendar program can help a technician by:","scheduling repair appointments and sending reminders",["sharpening blades","torquing bolts","measuring valves"],"Calendars schedule.")
H("875.d.7.B",3,"A turf-care company tracks each mower's route and mapped fields using satellite data. They are discussing:","Geographic Information Systems and Global Positioning Systems",["hand signals","a paper chart","telephone poles"],"GIS and GPS.")
H("875.d.7.B",4,"A GPS receiver on a piece of equipment provides its:","location, speed and route",["tire tread","engine oil type","spark gap"],"GPS gives position.")
H("875.d.7.C",3,"A technician plugs a diagnostic laptop into an engine control module to read live sensor data. This is:","using computer-based equipment",["guessing","manual only","unrelated to repair"],"Computers diagnose.")
H("875.d.7.C",4,"A computer-based diagnostic tool is useful because it can:","show stored fault codes and live data quickly",["replace parts","change oil","sharpen blades"],"Speeds diagnosis.")
H("875.d.8.A",3,"A student demonstrates how a generator engine, a tiller engine and a pump engine are each matched to a job. She is demonstrating:","the use and application of small engines and components",["paint","packaging","shipping"],"Match engine to task.")
H("875.d.8.A",4,"A small engine rated for continuous duty is best suited for a:","generator that runs for hours",["toy","wall clock","bike bell"],"Duty cycle matters.")
H("875.d.8.B",3,"A student traces current from the battery through the switch, coil and spark plug on a diagram. She is demonstrating:","the components of electrical-electronic systems",["fuel parts","exhaust parts","cooling parts"],"Trace the circuit.")
H("875.d.8.B",4,"The device that allows current to flow in only one direction in a charging circuit is the:","rectifier",["muffler","carburetor","dipstick"],"Rectifier converts AC to DC.")
H("875.d.8.C",3,"A technician compares side-valve, overhead-valve and two-cycle designs and the jobs each suits. He is demonstrating:","knowledge of engine designs, components and applications",["menu planning","tire shopping","paint mixing"],"Designs differ.")
H("875.d.8.C",4,"Overhead-valve engines are often favored over side-valve engines because they:","breathe better and burn fuel more efficiently",["use no oil","lack a camshaft","never overheat"],"Better combustion chamber.")
H("875.d.8.D",3,"A student reads cylinder wear with a dial bore gauge and tests the ignition with a spark tester. She is demonstrating:","the correct use of engine measuring tools and test equipment",["guessing","only visual checks","paint matching"],"Use the right tool.")
H("875.d.8.D",4,"A dial bore gauge measures a cylinder's:","inside diameter and any out-of-round wear",["outside paint thickness","tire tread","oil color"],"Bore gauges measure the inside.")
H("875.d.9.A",3,"A walk-behind mower surges, then stalls. The technician checks the fuel, filters the air and cleans the carburetor. She is:","troubleshooting and repairing a small engine",["painting","shopping","guessing"],"Systematic diagnosis.")
H("875.d.9.A",4,"After finding a stale-fuel varnish clog in a carburetor, the technician should also:","drain the old fuel and verify the engine runs properly",["ignore the tank","only repaint","skip the test run"],"Fix root cause.")
H("875.d.9.B",3,"A technician follows a seasonal list: change oil, replace the air filter, sharpen the blade and install a fresh spark plug. She is:","performing preventative maintenance on small engines",["waiting for failure","ignoring care","avoiding service"],"Routine service.")
H("875.d.9.B",4,"The main purpose of replacing an air filter on schedule is to:","prevent dirt from entering and wearing the engine",["make it louder","use more fuel","cool the exhaust"],"Clean air protects engines.")
H("875.d.9.C",3,"A technician tests a 4-stroke engine on regular gasoline and a leaner setting, then compares fuel use. She is:","assessing fuel mixtures and analyzing efficiency",["guessing","ignoring fuel","painting"],"Test and compare.")
H("875.d.9.D",3,"A student adjusts valve lash and aligns the cam timing marks on an overhead-valve engine. She is:","distinguishing valve arrangement positions and analyzing valve timing",["setting tire pressure","tuning a guitar","sharpening tools"],"Valve train work.")
H("875.d.9.D",4,"If an intake valve opens too late, the engine will likely:","lose power from poor cylinder filling",["gain power","run cooler only","use less oil"],"Late opening starves the cylinder.")
H("875.d.9.C",4,"A lean air-fuel mixture in an engine commonly causes:","overheating and possible engine damage",["extra lubrication","cooler running","no change"],"Lean runs hot.")
H("875.d.9.E",3,"A student changes the oil, tests the cooling fins for debris and checks the oil pump pickup screen. He is:","performing preventative maintenance on lubrication and cooling systems",["painting","guessing","avoiding service"],"Lube and cool.")
H("875.d.9.E",4,"Oil in an engine mainly reduces:","friction and wear, and helps carry heat away",["horsepower","fuel use only","air flow"],"Oil lubricates and cools.")
H("875.d.9.F",3,"A technician installs a new recoil starter, inspects the muffler bolts and adjusts the governor linkage. She is:","performing routine installations, inspections, adjustments and maintenance",["only painting","ignoring tasks","guessing"],"Routine service.")
H("875.d.9.F",4,"After adjusting an engine's governor, the technician should:","test the engine speed with a tachometer",["leave without testing","guess the speed","paint the housing"],"Verify the adjustment.")
H("875.d.9.G",3,"A student connects a multimeter, a timing light and a spark tester to a magneto ignition. She is demonstrating:","knowledge of electrical testing tools and equipment common to small engines",["only cleaning","only painting","only cutting"],"Test equipment.")
H("875.d.9.G",4,"A timing light is used to check:","when the spark occurs relative to piston position",["oil color","fuel octane","tire pressure"],"Timing light shows spark timing.")
H("875.d.9.H",3,"A student reads 0.750 inch on an outside micrometer measuring a piston pin. She is:","performing measurements using precision instruments",["guessing","using a yardstick","avoiding tools"],"Micrometers measure precisely.")
H("875.d.9.H",4,"An outside micrometer can measure to a precision of:","0.001 inch",["1 inch","0.5 inch","0.1 inch"],"Thousandths.")
H("875.d.9.I",3,"A technician measures a crankshaft journal and compares the reading with the manufacturer's wear limit. She is:","inspecting and measuring engine parts for wear tolerances and comparing them to specifications",["painting","ignoring specs","guessing"],"Compare to spec.")
H("875.d.9.I",4,"A measured piston-to-wall clearance greater than the service limit means the part:","is worn beyond tolerance and needs replacement or machining",["is like new","needs paint","can stay"],"Out of tolerance.")
H("875.d.9.J",3,"A student shows that a moving magnet next to a wire coil produces voltage, as in a flywheel magneto. She is demonstrating:","the relationship between electric current and magnetic fields",["fuel flow","oil flow","air flow"],"Electromagnetic induction.")
H("875.d.9.J",4,"Which part of a flywheel magneto passes the magnets near the coil?","the spinning flywheel",["the carburetor","the air cleaner","the muffler"],"The flywheel carries the magnets.")
H("875.d.9.K",3,"A technician finds a hot engine has a tighter piston fit than the same engine when cold. She is analyzing:","the effects of heating and cooling on small engines",["fuel pricing","tire wear","paint color"],"Thermal expansion.")
H("875.d.9.K",4,"Aluminum pistons expand faster than iron cylinders when heated, so they are fitted with:","a clearance to prevent seizing",["no clearance","tape","paint"],"Allow for expansion.")
H("875.d.9.L",3,"A student compares how thick a lubricating oil is at room temperature and when hot. She is explaining:","the thermophysical properties of fluids used in small engines",["colors only","pricing","packaging"],"Viscosity changes with heat.")
H("875.d.9.L",4,"A fluid's viscosity describes its:","resistance to flow",["color","price","smell"],"Thickness.")
H("875.d.9.M",3,"A student explains that energy cannot be created or destroyed, only changed from chemical to heat to motion in an engine. She is explaining:","the laws of thermodynamics",["motion pictures","tire laws","parking rules"],"First law.")
H("875.d.9.M",4,"The second law of thermodynamics helps explain why no engine can:","convert all fuel energy into useful work",["burn fuel","make heat","run at all"],"Some energy always becomes waste heat.")
H("875.d.9.N",3,"A student explains that torque twists the crankshaft, horsepower measures how fast work is done and some heat leaves through the exhaust. She is explaining:","torque, horsepower and heat energy transfer in small engines",["paint","tires","fuel taxes"],"Three key ideas.")
H("875.d.9.N",4,"Horsepower is a measure of:","the rate at which an engine does work",["fuel color","engine weight only","oil price"],"Power is work over time.")
H("875.d.9.O",3,"A technician times an engine's crankshaft at 3,600 revolutions each minute and calculates how fast the piston travels. She is:","calculating speed in small engines",["guessing","painting","naming parts"],"Speed calculations.")
H("875.d.9.O",4,"A mower engine speeds up from 2,000 rpm to 3,000 rpm in 5 seconds. Its acceleration is:","200 rpm per second",["500 rpm per second","1,000 rpm per second","15,000 rpm per second"],"1,000 ÷ 5 = 200.")
H("875.d.9.P",3,"A student compares the fuel used by a 3-hp and a 10-hp engine for the same job. She is:","comparing the efficiency of various engine sizes and types",["guessing","painting","naming tires"],"Compare efficiency.")
H("875.d.9.P",4,"An engine is more efficient when it:","converts more of the fuel's energy into useful work",["wastes more heat","burns more fuel","runs hotter"],"Efficiency means less waste.")
H("876.d.1.A",3,"A new automotive technician is asked to sign off an inspection he did not perform. His ethical and legal responsibility is to:","refuse and report only what he actually did",["sign it anyway","ask a friend to sign","hide the form"],"Honest records.")
H("876.d.1.A",4,"Which action best shows that a shop meets its legal duty for customers' safety?","repairing brake defects before returning the vehicle",["hiding the defect","skipping inspection","ignoring the manual"],"Fix safety items.")
H("876.d.1.B",3,"A trainee listens quietly while a veteran technician explains a procedure and thanks him afterward. She is showing:","proper etiquette and behavior",["rudeness","carelessness","lateness"],"Respect and gratitude.")
H("876.d.1.B",4,"A customer is upset that her car is not finished. The technician should:","apologize for the delay and give a realistic update",["avoid her","argue","promise a false time"],"Honest, calm.")
H("876.d.1.C",3,"An apprentice washes his hands, trims his sleeves and secures his hair before starting work. He is showing:","appropriate personal appearance and hygiene",["poor habits","unsafe dress","laziness"],"Clean and safe.")
H("876.d.1.C",4,"Long, loose sleeves are discouraged in a service bay because they can:","catch in rotating parts like belts and fans",["improve grip","reduce noise","save time"],"Entanglement hazard.")
H("876.d.1.D",3,"A technician emails the parts desk a request and speaks with a customer to confirm pickup. She is using:","effective written and oral communication skills and employability",["silence","text speak only","avoidance"],"Clear communication.")
H("876.d.1.D",4,"Which habit shows good listening during a customer's complaint?","repeating the concern back to confirm understanding",["looking at a phone","interrupting","walking away"],"Confirm understanding.")
H("876.d.1.E",3,"A student writes a step-by-step procedure for replacing a brake pad, with torque values and warnings in numbered order. She is demonstrating:","advanced technical writing and preparation skills",["story telling","poetry","jokes"],"Technical writing.")
H("876.d.1.E",4,"A well-written technical procedure should have steps that are:","clear, ordered and complete",["hidden","random","vague"],"Clarity.")
H("876.d.1.F",3,"A student presents the steps of a tire rotation to a class and answers an unplanned question on the spot. She is demonstrating:","prepared and extemporaneous speaking",["silent reading","mumbling","avoidance"],"Both types.")
H("876.d.1.F",4,"Which choice makes a technical talk clearer?","defining unfamiliar terms as you use them",["rushing","using no examples","speaking only in jargon"],"Define terms.")
H("876.d.2.A",3,"A service advisor calmly asks a customer from another town to describe a vibration, then repeats the symptoms back before writing the order. She shows:","effective oral communication with individuals from varied backgrounds",["poor listening","impatience","avoidance"],"Communicate with everyone.")
H("876.d.2.A",4,"When a customer is unfamiliar with automotive terms, the technician should:","explain the issue in plain words",["use only jargon","speak faster","avoid answering"],"Plain language.")
H("876.d.2.B",3,"A technician documents a vehicle's complaint, the cause found and the repair performed on the work order. She is demonstrating:","effective written communication, including documentation",["avoiding paper","random notes","slang only"],"Document the work.")
H("876.d.2.B",4,"A good written note on a work order is:","accurate, legible and specific",["vague","funny","unsigned"],"Be specific.")
H("876.d.2.C",3,"A technician multiplies 3.5 hours of labor by $90 and adds a $64 part. She is demonstrating:","mathematical skills in addition, subtraction, multiplication and division for estimates",["guessing","avoiding math","ignoring prices"],"Compute estimates.")
H("876.d.2.C",4,"If a customer has a $380 repair bill and a $50 coupon, the amount due is:","$330",["$430","$300","$350"],"380 − 50 = 330.")
H("876.d.3.A",3,"A student labels a diagram with the engine, fuel, electrical, cooling, exhaust, drivetrain, suspension and brake systems. She is describing:","the eight major vehicle systems",["tire types","paint finishes","trim levels"],"Eight systems.")
H("876.d.3.A",4,"Which is one of the eight major vehicle systems?","the steering and suspension system",["the radio dial","the cup holder","the wiper blade"],"Part of the eight.")
H("876.d.3.B",3,"A technician looks up the oil capacity and the recommended service interval for a specific car in the maintenance guide. She is:","locating, reading and interpreting vehicle maintenance and service information",["guessing","ignoring the manual","using memory only"],"Look it up.")
H("876.d.3.B",4,"Before replacing a timing belt, the technician should consult:","the manufacturer's service procedure for that vehicle",["a friend","a random video","her memory only"],"Follow the manufacturer.")
H("876.d.3.C",3,"A student explains how gasoline, diesel, hybrid and battery-electric vehicles supply power to the wheels. She is describing:","basic and emerging vehicle power systems",["horse power","paint types","tire sizes"],"Many power systems.")
H("876.d.3.C",4,"A key difference between a hybrid and a conventional vehicle is that a hybrid:","pairs an engine with an electric motor and battery",["has no brakes","has no engine ever","uses only wind"],"Hybrid combines two sources.")
H("876.d.4.A",3,"A student puts on safety glasses, checks that a drill's guard is in place and clamps the work before drilling. She is demonstrating:","the proper way to safely use hand and power tools and equipment",["unsafe habits","carelessness","ignoring rules"],"Tool safety.")
H("876.d.4.A",4,"Before using a power tool, a technician should inspect its cord and guards because:","damage could cause shock or injury",["it saves paint","it saves time","no one checks"],"Prevent accidents.")
H("876.d.4.B",3,"A shop sends used antifreeze and old brake fluid to licensed recyclers. This is the proper:","handling and disposal of environmentally hazardous materials",["dumping practice","drain disposal","trash disposal"],"Hazmat rules.")
H("876.d.4.B",4,"Safety Data Sheets (SDS) help a technician by describing:","a chemical's hazards and how to handle it safely",["its price","its color only","its brand history"],"SDS tell hazards.")
H("876.d.4.C",3,"A technician connects a scan tool to the vehicle's data port and reads the fault codes. She is:","identifying diagnostic tools and equipment",["guessing","using a hammer","painting"],"Diagnostic tools.")
H("876.d.4.C",4,"A digital multimeter is used to measure:","voltage, resistance and current",["tire wear","oil color","paint depth"],"Electrical testing.")
H("876.d.4.D",3,"A technician selects a socket set, a breaker bar and a torque wrench for a wheel job. She is:","identifying hand and shop tools and describing their proper usage",["guessing","ignoring tools","misusing tools"],"Right tool.")
H("876.d.4.D",4,"A torque wrench should be used to:","tighten fasteners to a specified value",["break bolts loose","hammer parts","cut metal"],"Measures torque.")
H("876.d.5.A",3,"A parts counter worker looks up a filter by year, make, model and engine, then confirms the part number. This demonstrates:","the procedures for ordering and locating parts",["guesswork","skipping steps","luck"],"Use a catalog.")
H("876.d.5.A",4,"The most reliable way to find a part is to match:","the vehicle's VIN with the part number",["the color","the radio","the price only"],"VIN identifies exactly.")
H("876.d.5.B",3,"A student walks through intake, compression, power and exhaust strokes on a model. She is demonstrating:","the operating theory of an internal combustion engine",["car painting","tire theory","brake theory"],"Four strokes.")
H("876.d.5.B",4,"In a four-stroke engine, the stroke in which the spark ignites the compressed mixture is the:","power stroke",["intake stroke","exhaust stroke","compression stroke"],"Power from combustion.")
H("876.d.5.C",3,"A student labels a rotor, caliper, pads, a drum, shoes and a booster on a brake diagram. She is identifying:","brake system components",["engine parts","tire parts","paint parts"],"Brake components.")
H("876.d.5.C",4,"Disc brakes slow a vehicle when the caliper squeezes the pads against the:","rotor",["tire","axle","muffler"],"Pads clamp the rotor.")
H("876.d.5.D",3,"A student explains that pressing the brake pedal pushes fluid through lines to the wheels, where pressure moves the pads. She is demonstrating:","basic concepts related to hydraulic brake systems",["fuel injection","tire rotation","ignition timing"],"Hydraulics.")
H("876.d.5.D",4,"Brake fluid is used in a hydraulic system because liquids:","do not compress easily and transmit force",["are cheap","burn quickly","evaporate fast"],"Fluid transfers pressure.")
H("876.d.5.E",3,"A student traces the battery, fuse, switch and headlight on a wiring diagram. She is demonstrating:","basic concepts related to electrical and electronic systems",["fuel systems","tire systems","cooling systems"],"Circuit basics.")
H("876.d.5.E",4,"The purpose of a fuse in a vehicle circuit is to:","protect the circuit by melting when current is too high",["increase voltage","store energy","speed the engine"],"Fuses protect.")
H("876.d.5.F",3,"A student identifies the compressor, condenser, evaporator and blower motor in the cabin cooling system. She is identifying:","air-conditioning, heating and accessory system components",["brake parts","engine blocks","tire valves"],"HVAC parts.")
H("876.d.5.F",4,"The component that removes heat from the refrigerant in an A/C system is the:","condenser",["wiper","horn","fuse"],"Condenser sheds heat.")
H("876.d.5.G",3,"A technician inspects a CV axle boot, a drive shaft and the transmission mount. She is inspecting:","chassis and power train components and systems",["decals","seat covers","paint"],"Chassis and power train.")
H("876.d.5.G",4,"A torn CV joint boot is a problem because it:","lets grease escape and dirt enter, damaging the joint",["improves the ride","adds power","reduces tire wear"],"Boots protect joints.")
H("876.d.5.H",3,"A student labels the radiator, water pump, thermostat and oil filter on an engine. She is identifying:","cooling and lubrication system components",["brake parts","tire parts","paint parts"],"Cooling and oil.")
H("876.d.5.H",4,"The thermostat in a cooling system:","regulates coolant flow to control engine temperature",["stores fuel","lights the dash","filters air"],"Opens when hot.")
H("876.d.5.I",3,"A technician inspects tie rods, ball joints, struts and the power steering pump. She is identifying:","steering and suspension components, including power steering",["fuel parts","paint parts","radio parts"],"Steering and suspension.")
H("876.d.5.I",4,"A worn tie rod end would most likely cause:","loose steering and uneven tire wear",["better mileage","a cooler engine","a louder radio"],"Worn steering parts.")
H("876.d.5.J",3,"A technician reads a tire sidewall code that shows size, load index and the Department of Transportation date code. She is:","identifying and interpreting tire sidewall data",["guessing","ignoring labels","painting"],"Read the sidewall.")
H("876.d.5.J",4,"The DOT code on a tire sidewall tells a technician the tire's:","manufacturing week and year",["price","owner","color"],"Date code.")
H("876.d.5.K",3,"A technician compares the recommended service intervals for a sedan, a diesel truck and a hybrid. She is:","comparing the preventative maintenance schedules for a variety of vehicles",["ignoring schedules","guessing","painting"],"Schedules differ.")
H("876.d.5.K",4,"A vehicle used for towing or in dusty conditions typically requires:","more frequent maintenance than normal driving",["less maintenance","no maintenance","maintenance only yearly"],"Severe service shortens intervals.")
H("876.d.5.L",3,"A technician checks fluid levels, tire pressure, belts, lights and brakes on a customer's car using a checklist. She is performing:","a preventative maintenance inspection",["a paint job","a sale","a rebuild"],"PM inspection.")
H("876.d.5.L",4,"The main goal of a preventative maintenance inspection is to:","find small problems before they cause breakdowns",["increase cost","cause delays","avoid service"],"Prevent failures.")
H("876.d.5.M",3,"A driver's battery is dead, and a technician connects jumper cables positive to positive, then negative to the dead car's metal frame. She is:","explaining and performing a jump-start properly",["wasting time","using wrong cables","doing a repair"],"Proper jump-start.")
H("876.d.5.M",4,"The last jumper cable clamp should be connected to an unpainted metal ground away from the battery to:","avoid sparks near the battery's explosive gases",["save cable","speed charging","look neat"],"Prevent explosions.")
